// Characterization tests: pin the current client-visible behavior of the HTTP API,
// including quirks, so a restructuring can't change them unnoticed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 2.5, gold: 200, odd: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

async function create(items) {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const { res, body } = await create([{ sku: 'apple', qty: 3 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.deepEqual(body.items, [{ sku: 'apple', qty: 3 }])
  assert.equal(body.total, 30)
})

test('ids are sequential strings', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body.id
  const b = (await create([{ sku: 'apple', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('total sums multiple items', async () => {
  const { body } = await create([{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 4 }])
  assert.equal(body.total, 30)
})

test('total is floored to an integer', async () => {
  const { body } = await create([{ sku: 'pear', qty: 3 }]) // 7.5
  assert.equal(body.total, 7)
})

test('no discount at exactly 100', async () => {
  const { body } = await create([{ sku: 'apple', qty: 10 }])
  assert.equal(body.total, 100)
})

test('10% discount applies above 100', async () => {
  const { body } = await create([{ sku: 'apple', qty: 11 }]) // 110 -> 99
  assert.equal(body.total, 99)
})

test('discount then floor', async () => {
  const { body } = await create([{ sku: 'odd', qty: 4 }]) // 133.32 -> 119.988 -> 119
  assert.equal(body.total, 119)
})

test('discount applies to large totals', async () => {
  const { body } = await create([{ sku: 'gold', qty: 1 }]) // 200 -> 180
  assert.equal(body.total, 180)
})

test('invalid requests return 400 { error: "items required" }', async () => {
  const cases = [
    post({}),
    post({ items: [] }),
    post({ items: 'apple' }),
    post(null, 'not json'),
    post(null, ''),
  ]
  for (const p of cases) {
    const res = await p
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns a created order', async () => {
  const { body: created } = await create([{ sku: 'apple', qty: 2 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with { error: "not found" } (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  const reqs = [
    fetch(`${base}/`),
    fetch(`${base}/nope`),
    fetch(`${base}/orders`),
    fetch(`${base}/orders/1/extra`),
    fetch(`${base}/orders/1`, { method: 'DELETE' }),
    fetch(`${base}/orders/1`, { method: 'POST' }),
  ]
  for (const p of reqs) {
    const res = await p
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
